Конечно же, не может все закончиться на объявлении типа! Мне удалось не только воссоздать похудевшую версию неугодного
std::string
, но и создать некоторые фичи. Например, хэширование для быстрого сравнения строк.
static inline uint32_t strhash(const string* s) {
 if (s == NULL || !strok(s)) return 0;

 const char* data = strdata(s);
 uint32_t len = strlen_s(s);

 uintptr_t data_ptr = (uintptr_t)data;
 uintptr_t len_ptr = (uintptr_t)(is_sso(s) ?
 (const void*)&s->sso_len :
 (const void*)&s->len);

 uint32_t hash = (uint32_t)(data_ptr ^ len_ptr ^ (uintptr_t)len);

 if (len >= 2) {
 hash ^= (uint8_t)data[0] | ((uint8_t)data[1] << 8);
 } else if (len == 1) {
 hash ^= (uint8_t)data[0];
 }

 hash ^= hash >> 16;
 hash *= 0x9e3779b9;
 hash ^= hash >> 16;

 return hash;
}
